def _clean_dialed_number(raw: str) -> str:
    """
    Strip formatting characters and normalize an international access prefix.

    A leading ``00`` (the IDD access code used across most of the world) is
    equivalent to a leading ``+``, so both are collapsed to the ``+`` form that
    ``phonenumbers`` understands without a region hint.
    """
    cleaned = _NON_DIGIT_RE.sub("", (raw or "").replace(" ", ""))
    if cleaned.startswith("+"):
        return "+" + cleaned[1:].lstrip("+")
    if cleaned.startswith("00") and len(cleaned) > 2:
        return "+" + cleaned[2:]
    return cleaned


