def _humanize_loan_type_id(loan_type_id: str) -> str:
    """Render an unknown/legacy id as a readable label (``hard_money`` → ``Hard Money``)."""
    spaced = re.sub(r"\s+", " ", re.sub(r"[_\-]+", " ", loan_type_id)).strip()
    if not spaced:
        return loan_type_id.strip()
    return spaced.title()


def loan_type_label(loan_type_id: Optional[str]) -> str:
    if not loan_type_id:
        return ""
    for choice in LOAN_TYPE_CHOICES:
        if choice["id"] == loan_type_id:
            return choice["label"]
    return _humanize_loan_type_id(loan_type_id)


