function normalizeKey(value: string): string {
  return value.trim().toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
}

export function resolveLoanTypeId(raw: string): string | null {
  const value = raw.trim();
  if (!value) return null;
  const compact = value.toLowerCase().replace(/[\s_-]+/g, "");
  if (LOAN_TYPE_LABEL_MAP[compact]) return compact;
  if (LOAN_TYPE_LABEL_MAP[value.toLowerCase()]) return value.toLowerCase();
  const normalized = normalizeKey(value);
  if (LOAN_TYPE_ALIASES[normalized]) return LOAN_TYPE_ALIASES[normalized];
  for (const opt of CRM_LOAN_TYPE_OPTIONS) {
    if (normalizeKey(opt.label) === normalized) return opt.id;
  }
  return null;
}

export function getCrmLoanTypeLabel(loanType?: string | null): string {
  if (!loanType) return "";
  return LOAN_TYPE_LABEL_MAP[loanType] ?? loanType.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

export function parseTagsInput(raw: string): string[] {
  return raw
    .split(/[;,]/)
    .map((t) => t.trim().toLowerCase())
    .filter(Boolean);
}

export function formatTagsForInput(tags?: string[]): string {
  return (tags ?? []).join(", ");
}
